#!/usr/bin/env bash
inv(){ local root=$1 out=$2; (cd "$root" && find . -type f -printf '%P\t%m\t%s\t' | LC_ALL=C sort | while IFS=$'\t' read -r p m s; do printf '%s\t%s\t%s\t' "$p" "$m" "$s"; sha256sum "$p"|cut -d' ' -f1; done)>"$out"; }
owner(){ case "$1" in FieldTransportAtlas|SurfaceCellAuthorityKernel) echo directional_surface_cell_authority_kernel_tests;; FlowRepStrandsPhase15|PatchDescriptorMilestoneE|PureQuadCompletionPhase18|SurfaceArrangementPhase16|SurfaceCellSourceSupportAndChartAuthority|SurfaceComplexSimplificationPhase17) echo directional_surface_cell_completion_tests;; SourceAuthoritativeMeshValidatorPhase22|SurfaceMeshOptimizerPhase19|SurfaceMeshOptimizerPhase22|SurfaceOptimizationRailAuthorityMigration) echo directional_surface_cell_validation_tests;; *) echo directional_surface_cell_producer_tests;; esac; }
run1(){ local phase=$1 id=$2 bin=$3 ord=${4:-NA}; local p="$E/processes/${phase}-$(printf '%s' "$ord-$id"|sha256sum|cut -c1-16)"; python3 "$H" "$W/package/bin/$bin" "$id" "$p" > "$p.harness.log" 2>&1 || return 90; local rc cnt ms; rc=$(jq -r .returncode "$p.json"); cnt=$(jq -r .run_count "$p.json"); ms=$(jq -r .elapsed_ms "$p.json"); printf '%s\t%s\t%s\t%s\t%s\t%s\t%s\n' "$phase" "$ord" "$id" "$bin" "$rc" "$cnt" "$ms" >> "$E/execution-ledger.tsv"; [[ "$cnt" == 1 ]] || return 91; [[ "$rc" =~ ^-?[0-9]+$ ]] || return 92; RUN_RC=$rc; }
post(){ local tag=$1 ok=1; if [[ $HAVE_BASE == 1 ]]; then inv "$W/package" "$E/package-after.tsv" || ok=0; inv "$GITHUB_WORKSPACE" "$E/source-after.tsv" || ok=0; cmp -s "$E/package-before.tsv" "$E/package-after.tsv" || ok=0; cmp -s "$E/source-before.tsv" "$E/source-after.tsv" || ok=0; (cd "$W/package" && sha256sum -c SHA256SUMS > "$E/postflight-sha256sums.txt" 2>&1) || ok=0; fi; [[ -f "$W/package.zip" && $(sha256sum "$W/package.zip"|cut -d' ' -f1) == "$OUTER" ]] || ok=0; printf 'phase=%s\npostflight_integrity=%s\nbenchmarkExecution=false\nconfigure=false\ncompile=false\nrelink=false\nrepair=false\ngeneratedDiscovery=false\nsourceMutation=false\ntestMutation=false\nfixtureMutation=false\nselectorMutation=false\npackageMutation=false\n' "$tag" "$([[ $ok == 1 ]]&&echo pass||echo fail)" > "$E/postflight.txt"; [[ $ok == 1 ]]; }
finish(){ local ex=$1; post R8-postflight || { STATUS=ORCHESTRATION_RED; REASON=postflight_integrity_failure; ex=2; }; if [[ $FIRST_RED -gt 0 ]]; then printf 'selector-after-%s\tNOT-RUN\tfirst-semantic-red\n' "$FIRST_RED" >> "$E/not-run.tsv"; fi; printf 'benchmarks\tNOT-RUN\tfrozen-R8-non-action\n' >> "$E/not-run.tsv"; jq -n --arg status "$STATUS" --arg reason "$REASON" --arg semantic "$SEM_SRC" --arg build "$BUILD_SRC" --arg artifact "$ART" --arg selector "$H365" --argjson runtime "$RUNTIME" --argjson accepted "$ACCEPTED_GREEN" --argjson checkpoint "$CHECKPOINT_GREEN" --argjson red "$FIRST_RED" '{turn:"M3-CP4c-2-TB-X2-R8-EXEC",status:$status,reason:$reason,semantic_source:$semantic,build_transport_source:$build,artifact_id:$artifact,selector_sha256:$selector,runtime_started:($runtime==1),accepted_green:$accepted,checkpoint_green:$checkpoint,first_red_ordinal:$red,selected_r2_branch:"NONE",selected_gate:"365",gate_execution_authorized:true,benchmarkExecution:false}' > "$R/summary.json"; cp "$E/execution-ledger.tsv" "$E/not-run.tsv" "$E/postflight.txt" "$E/gate-authority.txt" "$R/" 2>/dev/null || true; tar -C "$E" -czf "$R/Directional__M3-CP4c-2-TB-X2-R8-EXEC__raw-evidence.tar.gz" .; sha256sum "$R/Directional__M3-CP4c-2-TB-X2-R8-EXEC__raw-evidence.tar.gz" > "$R/raw-evidence.sha256"; echo "$ex" > "$R/execution-exit-code.txt"; exit "$ex"; }
